 body={"success":true,"count":10,"pagination":{"next":{"page":2,"limit":10}},"data":[{"_id":"68e57738d41f32edaaa5d169","customId":"10","title":"Interstellar","synopsis":"A team of explorers travel through a wormhole in space in an attempt to ensure humanity's survival.","director":"Christopher Nolan","genres":["Adventure","Drama","Science Fiction"],"duration":169,"classification":"PG-13","poster":"interstellar.jpg","releaseDate":"2014-11-07T00:00:00.000Z","id":"68e57738d41f32edaaa5d169"},{"_id":"68e57737acee46196cffd70d","customId":"2","title":"The Avengers","synopsis":"Earth's mightiest heroes must come together to save the world.","director":"Joss Whedon","genres":["Action","Adventure"],"duration":143,"classification":"PG-13","poster":"avengers.jpg","releaseDate":"2012-05-04T00:00:00.000Z","id":"68e57737acee46196cffd70d"},{"_id":"68e57737acee46196cffd70c","customId":"1","title":"Inception","synopsis":"A thief who enters the dreams of others to steal their secrets.","director":"Christopher Nolan","genres":["Science Fiction","Action"],"duration":148,"classification":"PG-13","poster":"inception.jpg","releaseDate":"2010-07-16T00:00:00.000Z","id":"68e57737acee46196cffd70c"},{"_id":"68e57738d41f32edaaa5d16d","customId":"14","title":"Avatar","synopsis":"A paraplegic Marine dispatched to the moon Pandora on a unique mission becomes torn between following his orders and protecting the world he feels is his home.","director":"James Cameron","genres":["Action","Adventure","Fantasy"],"duration":162,"classification":"PG-13","poster":"avatar.jpg","releaseDate":"2009-12-18T00:00:00.000Z","id":"68e57738d41f32edaaa5d16d"},{"_id":"68e57738d41f32edaaa5d165","customId":"6","title":"The Dark Knight","synopsis":"When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.","director":"Christopher Nolan","genres":["Action","Crime","Drama"],"duration":152,"classification":"PG-13","poster":"darkknight.jpg","releaseDate":"2008-07-18T00:00:00.000Z","id":"68e57738d41f32edaaa5d165"},{"_id":"68e57738d41f32edaaa5d16b","customId":"12","title":"The Lord of the Rings: The Fellowship of the Ring","synopsis":"A meek Hobbit from the Shire and eight companions set out on a journey to destroy the powerful One Ring and save Middle-earth from the Dark Lord Sauron.","director":"Peter Jackson","genres":["Adventure","Fantasy","Drama"],"duration":178,"classification":"PG-13","poster":"lotr.jpg","releaseDate":"2001-12-19T00:00:00.000Z","id":"68e57738d41f32edaaa5d16b"},{"_id":"68e57738d41f32edaaa5d16a","customId":"11","title":"Gladiator","synopsis":"A former Roman General sets out to exact vengeance against the corrupt emperor who murdered his family and sent him into slavery.","director":"Ridley Scott","genres":["Action","Adventure","Drama"],"duration":155,"classification":"R","poster":"gladiator.jpg","releaseDate":"2000-05-05T00:00:00.000Z","id":"68e57738d41f32edaaa5d16a"},{"_id":"68e57738d41f32edaaa5d166","customId":"7","title":"Fight Club","synopsis":"An insomniac office worker and a devil-may-care soapmaker form an underground fight club that evolves into something much, much more.","director":"David Fincher","genres":["Drama"],"duration":139,"classification":"R","poster":"fightclub.jpg","releaseDate":"1999-10-15T00:00:00.000Z","id":"68e57738d41f32edaaa5d166"},{"_id":"68e57738d41f32edaaa5d163","customId":"4","title":"The Matrix","synopsis":"A computer hacker learns from mysterious rebels about the true nature of his reality and his role in the war against its controllers.","director":"Lana Wachowski, Lilly Wachowski","genres":["Science Fiction","Action"],"duration":136,"classification":"R","poster":"matrix.jpg","releaseDate":"1999-03-31T00:00:00.000Z","id":"68e57738d41f32edaaa5d163"},{"_id":"68e57738d41f32edaaa5d16c","customId":"13","title":"Titanic","synopsis":"A seventeen-year-old aristocrat falls in love with a kind but poor artist aboard the luxurious, ill-fated R.M.S. Titanic.","director":"James Cameron","genres":["Drama","Romance"],"duration":194,"classification":"PG-13","poster":"titanic.jpg","releaseDate":"1997-12-19T00:00:00.000Z","id":"68e57738d41f32edaaa5d16c"}]}

